// Generated by Automated Quality Gate; review before merging.
const {
  add,
  subtract,
  multiply,
  divide,
  calculatePercentage,
  modulo,
  absoluteDifference
} = require('../../src/math');

describe('math.js utility functions', () => {
  describe('validation logic', () => {
    test('should throw TypeError for non-number inputs', () => {
      expect(() => add('1', 2)).toThrow('Inputs must be valid numbers');
      expect(() => add(null, 2)).toThrow('Inputs must be valid numbers');
      expect(() => add(undefined, 2)).toThrow('Inputs must be valid numbers');
    });

    test('should throw TypeError for NaN', () => {
      expect(() => add(NaN, 5)).toThrow('Inputs must be valid numbers');
    });

    test('should throw TypeError for Infinity', () => {
      expect(() => add(Infinity, 5)).toThrow('Inputs must be finite numbers');
      expect(() => add(5, -Infinity)).toThrow('Inputs must be finite numbers');
    });
  });

  describe('add', () => {
    test('should add two positive numbers', () => {
      expect(add(2, 3)).toBe(5);
    });
  });

  describe('subtract', () => {
    test('should normalize -0 to 0', () => {
      const result = subtract(5, 5);
      expect(result).toBe(0);
      expect(Object.is(result, -0)).toBe(false);
    });
  });

  describe('multiply', () => {
    test('should multiply negative numbers', () => {
      expect(multiply(-2, -3)).toBe(6);
    });
  });

  describe('divide', () => {
    test('should throw error on division by zero', () => {
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
      expect(() => divide(10, -0)).toThrow('Cannot divide by zero');
    });

    test('should return correct quotient', () => {
      expect(divide(10, 2)).toBe(5);
    });
  });

  describe('calculatePercentage', () => {
    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(50, 0)).toBe(0);
    });

    test('should calculate percentage correctly', () => {
      expect(calculatePercentage(25, 100)).toBe(25);
    });
  });

  describe('modulo', () => {
    test('should perform mathematical modulo correctly', () => {
      expect(modulo(-7, 4)).toBe(1);
      expect(modulo(7, 4)).toBe(3);
    });

    test('should throw error on modulo by zero', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should return the absolute difference between two numbers', () => {
      expect(absoluteDifference(5, 10)).toBe(5);
      expect(absoluteDifference(10, 5)).toBe(5);
      expect(absoluteDifference(-5, 5)).toBe(10);
    });
  });
});
